package org.nonfood.oilplants.web;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import org.nonfood.oilplants.dao.UserDao;import org.nonfood.oilplants.service.UserService;import java.io.*;
@WebServlet("/profile") public class ProfileServlet extends HttpServlet{
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{r.setAttribute("profile",new UserDao().findById(WebSupport.user(r).getId()).orElseThrow());WebSupport.view(r,s,"user/profile");}catch(Exception e){WebSupport.error(r,s,e,"个人信息暂时不可用。");}}
 protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{UserService svc=new UserService();long id=WebSupport.user(r).getId();if("password".equals(r.getParameter("action"))){svc.updatePassword(id,r.getParameter("oldPassword"),r.getParameter("password"),r.getParameter("confirmPassword"));r.setAttribute("success","密码已更新。");}else{svc.updateProfile(id,r.getParameter("displayName"),r.getParameter("email"));var u=new UserDao().findById(id).orElseThrow();u.setPasswordHash(null);r.getSession().setAttribute(WebSupport.USER,u);r.setAttribute("success","个人资料已保存。");}r.setAttribute("profile",new UserDao().findById(id).orElseThrow());WebSupport.view(r,s,"user/profile");}catch(Exception e){r.setAttribute("error",e.getMessage());doGet(r,s);}}
}
